#!/bin/bash
# Generated By: Claude Code (Claude Opus 4.6)
# Validate sandbox profile configuration. No secrets in output.
# Run inside sandbox: /sandbox/bin/validate-profile.sh
# Called by claude-wrapper.sh before launching Claude CLI.

set -euo pipefail

RED='\033[0;31m'
GREEN='\033[0;32m'
BROWN='\033[0;33m'
LIGHT_PURPLE='\033[1;35m'
NC='\033[0m'

pass=0
fail=0
RESULTS=""

check() {
    local description="$1" expected="$2" actual="$3"
    local verdict
    if [[ "$expected" == "$actual" ]]; then
        verdict="PASS"
        pass=$((pass + 1))
    else
        verdict="FAIL"
        fail=$((fail + 1))
    fi
    RESULTS+="${description}|${expected}|${actual}|${verdict}"$'\n'
}

isset() { [[ -n "${!1+x}" && -n "${!1}" ]]; }

net_check() {
    local code
    # --max-time is required, not just --connect-timeout: the OpenShell L7 proxy
    # can accept the TCP connection and then never respond, which stalls curl forever.
    code=$(curl -so /dev/null -w '%{http_code}' --connect-timeout 3 --max-time 8 "$1" 2>/dev/null) || code="000"
    # 403 = OpenShell L7 proxy rejected the request (blocked by policy)
    if [[ "$code" == "403" || "$code" == "000" ]]; then
        echo "blocked"
    else
        echo "reachable"
    fi
}

PROFILE="${SANDBOX_PROFILE:-work}"

# personal, home and codex carry no work credentials; home is personal plus the
# Prometheus and Loki reads checked below, and codex is home with OpenAI in
# place of Anthropic. Every other expectation is shared, so the three are one
# case here.
personal_profile() { [[ "$PROFILE" == personal || "$PROFILE" == home || "$PROFILE" == codex ]]; }

# The one profile whose agent is not Claude. Separate from the above because it
# answers a different question: which API this sandbox is supposed to reach.
codex_profile() { [[ "$PROFILE" == codex ]]; }
# Profiles that may reach OpenAI. The codex profile swaps Anthropic out for it;
# work carries both, because a work sandbox runs both agents.
openai_profile() { [[ "$PROFILE" == codex || "$PROFILE" == work ]]; }

if personal_profile; then
    C_PROFILE="$LIGHT_PURPLE"
else
    C_PROFILE="$BROWN"
fi

# --- Auth ---
if codex_profile; then
    # Codex writes $CODEX_HOME/auth.json for both sign-in methods — ChatGPT
    # OAuth and `--with-api-key` alike — so the file is the whole test. Nothing
    # uploads it from the host and nothing preserves it across --recreate, so
    # "unset" here is the expected state of a fresh sandbox and the prompt to
    # run `codex login --device-auth`.
    if isset OPENAI_API_KEY; then
        check "codex auth (API key)" "set" "set"
    elif [[ -f /sandbox/.codex/auth.json ]]; then
        check "codex auth (auth.json)" "set" "set"
    else
        check "codex auth (run codex login)" "set" "unset"
    fi

    isset ANTHROPIC_API_KEY && check "ANTHROPIC_API_KEY" "unset" "set" || check "ANTHROPIC_API_KEY" "unset" "unset"

    leaked=$(env | grep -iE "^(GOOGLE|CLOUDSDK|CLOUD_ML|VERTEX|ANTHROPIC_VERTEX)_" | cut -d= -f1) || true
    if [[ -n "$leaked" ]]; then
        for var in $leaked; do
            check "$var" "unset" "set"
        done
    else
        check "Google/Vertex vars" "unset" "unset"
    fi
elif personal_profile; then
    has_oauth=$([[ -f /sandbox/.claude/.credentials.json ]] && echo "yes" || echo "no")
    if isset ANTHROPIC_API_KEY; then
        check "personal auth (API key)" "set" "set"
    elif [[ "$has_oauth" == "yes" ]]; then
        check "personal auth (OAuth)" "set" "set"
    else
        check "personal auth (API key or OAuth)" "set" "unset"
    fi

    leaked=$(env | grep -iE "^(GOOGLE|CLOUDSDK|CLOUD_ML|VERTEX|ANTHROPIC_VERTEX)_" | cut -d= -f1) || true
    if [[ -n "$leaked" ]]; then
        for var in $leaked; do
            check "$var" "unset" "set"
        done
    else
        check "Google/Vertex vars" "unset" "unset"
    fi
else
    isset CLAUDE_CODE_USE_VERTEX && check "CLAUDE_CODE_USE_VERTEX" "set" "set" || check "CLAUDE_CODE_USE_VERTEX" "set" "unset"
    isset ANTHROPIC_VERTEX_PROJECT_ID && check "ANTHROPIC_VERTEX_PROJECT_ID" "set" "set" || check "ANTHROPIC_VERTEX_PROJECT_ID" "set" "unset"
    isset ANTHROPIC_API_KEY && check "ANTHROPIC_API_KEY" "unset" "set" || check "ANTHROPIC_API_KEY" "unset" "unset"
fi

# --- Jira ---
if personal_profile; then
    leaked=$(env | grep -iE "^(JIRA|ATLASSIAN)_" | cut -d= -f1) || true
    if [[ -n "$leaked" ]]; then
        for var in $leaked; do
            check "$var" "unset" "set"
        done
    else
        check "Jira/Atlassian vars" "unset" "unset"
    fi
else
    isset JIRA_TOKEN && check "JIRA_TOKEN" "set" "set" || check "JIRA_TOKEN" "set" "unset"
    isset JIRA_URL && check "JIRA_URL" "set" "set" || check "JIRA_URL" "set" "unset"
fi

# --- Credentials on disk ---
if personal_profile; then
    [[ -d /sandbox/.config/gcloud ]] && check "gcloud config dir" "absent" "present" || check "gcloud config dir" "absent" "absent"
    [[ -d /sandbox/.config/gws ]] && check "gws config dir" "absent" "present" || check "gws config dir" "absent" "absent"
else
    [[ -d /sandbox/.config/gcloud ]] && check "gcloud config dir" "present" "present" || check "gcloud config dir" "present" "absent"
    [[ -d /sandbox/.config/gws ]] && check "gws config dir" "present" "present" || check "gws config dir" "present" "absent"
fi

# --- OTEL ---
isset CLAUDE_CODE_ENABLE_TELEMETRY && check "OTEL telemetry" "enabled" "enabled" || check "OTEL telemetry" "enabled" "disabled"
isset OTEL_EXPORTER_OTLP_ENDPOINT && check "OTLP endpoint" "set" "set" || check "OTLP endpoint" "set" "unset"
isset SANDBOX_PROFILE && check "SANDBOX_PROFILE (OTEL tag)" "set" "set" || check "SANDBOX_PROFILE (OTEL tag)" "set" "unset"

# --- Network ---
if command -v curl &>/dev/null; then
    # The swap is asserted in both directions. A codex sandbox that can still
    # reach Anthropic is a home sandbox with an extra CLI in it, and nothing in
    # a running session would say which agent it was talking to.
    actual=$(net_check https://api.anthropic.com)
    if codex_profile; then
        check "api.anthropic.com" "blocked" "$actual"
    elif personal_profile; then
        check "api.anthropic.com" "reachable" "$actual"
    else
        check "api.anthropic.com" "blocked" "$actual"
    fi

    # Three hosts, three failure modes: chatgpt.com is the default provider on a
    # ChatGPT sign-in, api.openai.com the provider on an API key, and
    # auth.openai.com every login and token refresh. Checking one would leave
    # two ways to be silently broken.
    for host in chatgpt.com api.openai.com auth.openai.com; do
        actual=$(net_check "https://${host}")
        openai_profile && check "$host" "reachable" "$actual" || check "$host" "blocked" "$actual"
    done

    actual=$(net_check https://us-east5-aiplatform.googleapis.com)
    personal_profile && check "googleapis.com" "blocked" "$actual" || check "googleapis.com" "reachable" "$actual"

    actual=$(net_check https://redhat.atlassian.net)
    personal_profile && check "redhat.atlassian.net" "blocked" "$actual" || check "redhat.atlassian.net" "reachable" "$actual"

    # Telemetry query endpoints are site-specific and arrive via /sandbox/.env.
    # A missing URL fails rather than skips: a skipped check reads the same as
    # a passing one, so an endpoint that is actually reachable would go unseen.
    # The one axis where personal parts company with home and codex: those two
    # may read the telemetry back, personal may only push it.
    [[ "$PROFILE" == "personal" ]] && query_expect="blocked" || query_expect="reachable"
    if isset SANDBOX_PROMETHEUS_URL; then
        actual=$(net_check "$SANDBOX_PROMETHEUS_URL")
    else
        actual="no SANDBOX_PROMETHEUS_URL in .env"
    fi
    check "prometheus" "$query_expect" "$actual"

    if isset SANDBOX_LOKI_URL; then
        actual=$(net_check "$SANDBOX_LOKI_URL")
    else
        actual="no SANDBOX_LOKI_URL in .env"
    fi
    check "loki" "$query_expect" "$actual"

    # Collector endpoint comes from the same env var Claude Code exports to.
    # A GET on an OTLP receiver returns 405; that still proves reachability.
    if isset OTEL_EXPORTER_OTLP_ENDPOINT; then
        actual=$(net_check "${OTEL_EXPORTER_OTLP_ENDPOINT%/}/v1/logs")
    else
        actual="no OTEL_EXPORTER_OTLP_ENDPOINT set in .env"
    fi
    check "OTEL collector" "reachable" "$actual"
fi

# --- Git auth (no sandbox should have git auth) ---
# ConnectTimeout only bounds the TCP handshake, so wrap in `timeout` for the
# case where the proxy connects and then hangs.
# Capture output instead of piping to grep: `ssh -T git@github.com` exits 1 even
# when auth SUCCEEDS (GitHub prints the greeting, then closes — no shell access).
# Under `set -o pipefail` that non-zero sank the whole pipeline, so the check
# reported "blocked" unconditionally and could never detect leaked SSH auth.
ssh_out=$(timeout 8 ssh -o ConnectTimeout=3 -o BatchMode=yes \
    -o StrictHostKeyChecking=no -T git@github.com 2>&1 || true)
if [[ "$ssh_out" == *"successfully authenticated"* ]]; then
    git_ssh="authed"
else
    git_ssh="blocked"
fi
check "GitHub SSH" "blocked" "$git_ssh"

# GIT_TERMINAL_PROMPT=0 stops git from blocking on a credential prompt.
GIT_TERMINAL_PROMPT=0 timeout 8 git ls-remote https://github.com/jewzaam/openshell-sandbox.git HEAD &>/dev/null && git_https="authed" || git_https="blocked"
check "GitHub HTTPS" "blocked" "$git_https"

# --- Output ---
echo ""
echo "==============================="
echo -e "Profile is:  ${C_PROFILE}${PROFILE}${NC}"
echo "==============================="
echo ""
FMT="  %-30s  %-12s  %-12s  %s\n"
printf "$FMT" "CHECK" "EXPECTED" "ACTUAL" "RESULT"
printf "$FMT" "──────────────────────────────" "────────────" "────────────" "──────"
while IFS='|' read -r desc exp act verdict; do
    [[ -z "$desc" ]] && continue
    local_color="$GREEN"
    [[ "$verdict" == "FAIL" ]] && local_color="$RED"
    printf "  %-30s  %-12s  %-12s  ${local_color}%s${NC}\n" "$desc" "$exp" "$act" "$verdict"
done <<< "$RESULTS"
echo ""
if [[ $fail -eq 0 ]]; then
    echo -e "Summary: ${C_PROFILE}${PROFILE}${NC}  ${GREEN}PASS${NC}  (${pass} checks passed)"
else
    echo -e "Summary: ${C_PROFILE}${PROFILE}${NC}  ${RED}FAIL${NC}  (${fail} failed, ${pass} passed)"
fi
echo ""

exit $fail
